<?php
require '_layout.php'; admin_start('Dashboard');
$rg = $_GET['range'] ?? '1m'; [$from, $to] = range_dates($rg); $days = max(1, (strtotime($to) - strtotime($from)) / 86400 + 1);
$pf = date('Y-m-d', strtotime("$from -$days days")); $pt = date('Y-m-d', strtotime("$from -1 day"));
$REV = "status IN " . REV_STATUS;
$rev = fn($a, $b) => (float)val("SELECT COALESCE(SUM(total),0) FROM orders WHERE $REV AND DATE(created_at) BETWEEN ? AND ?", [$a, $b]);
$cnt = fn($a, $b) => (int)val("SELECT COUNT(*) FROM orders WHERE DATE(created_at) BETWEEN ? AND ?", [$a, $b]);
$cus = fn($a, $b) => (int)val("SELECT COUNT(*) FROM users WHERE role='customer' AND DATE(created_at) BETWEEN ? AND ?", [$a, $b]);
$vis = fn($a, $b) => (int)val("SELECT COUNT(DISTINCT ip) FROM visitors WHERE visit_date BETWEEN ? AND ?", [$a, $b]);
$series = function ($sql) use ($from, $to, $days) { $m = array_column(rows($sql, [$from, $to]), 'v', 'd'); $o = []; for ($i = 0; $i < $days; $i++) $o[] = (float)($m[date('Y-m-d', strtotime("$from +$i days"))] ?? 0); return $o; };
$sRev = $series("SELECT DATE(created_at) d, SUM(total) v FROM orders WHERE $REV AND DATE(created_at) BETWEEN ? AND ? GROUP BY d");
$sOrd = $series("SELECT DATE(created_at) d, COUNT(*) v FROM orders WHERE DATE(created_at) BETWEEN ? AND ? GROUP BY d");
$sCus = $series("SELECT DATE(created_at) d, COUNT(*) v FROM users WHERE role='customer' AND DATE(created_at) BETWEEN ? AND ? GROUP BY d");
$sVis = $series("SELECT visit_date d, COUNT(DISTINCT ip) v FROM visitors WHERE visit_date BETWEEN ? AND ? GROUP BY d");
$labels = []; for ($i = 0; $i < $days; $i++) $labels[] = date('d M', strtotime("$from +$i days"));
$revN = $rev($from, $to);
$cards = [['Total Revenue', money($revN), pct_change($revN, $rev($pf, $pt)), '🛒', 'g', $sRev, '#2db55d'], ['Total Orders', number_format($cnt($from, $to)), pct_change($cnt($from, $to), $cnt($pf, $pt)), '🛒', 'o', $sOrd, '#f6a53e'], ['New Customers', number_format($cus($from, $to)), pct_change($cus($from, $to), $cus($pf, $pt)), '👥', 'b', $sCus, '#4c8dff'], ['Website Visitors', number_format($vis($from, $to)), pct_change($vis($from, $to), $vis($pf, $pt)), '👁', 'p', $sVis, '#9a6bff']];
$st = array_column(rows("SELECT status, COUNT(*) c FROM orders WHERE DATE(created_at) BETWEEN ? AND ? GROUP BY status", [$from, $to]), 'c', 'status');
$recent = rows('SELECT * FROM orders ORDER BY id DESC LIMIT 6'); $top = rows('SELECT * FROM products ORDER BY sold DESC LIMIT 4');
$low = rows('SELECT id,name_en,stock FROM products WHERE stock<=? AND status=1 ORDER BY stock LIMIT 5', [(int)S('low_stock', 10)]);
$dev = array_column(rows('SELECT device, COUNT(*) c FROM visitors WHERE visit_date BETWEEN ? AND ? GROUP BY device', [$from, $to]), 'c', 'device'); $vtot = array_sum($dev);
$src = rows("SELECT CASE WHEN referrer='' OR referrer IS NULL THEN 'Direct' WHEN referrer REGEXP 'google|bing|yahoo|duckduckgo' THEN 'Search' WHEN referrer REGEXP 'facebook|instagram|youtube|twitter|t\\\\.co|linkedin|pinterest|whatsapp' THEN 'Social Media' ELSE 'Referral' END s, COUNT(*) c FROM visitors WHERE visit_date BETWEEN ? AND ? GROUP BY s ORDER BY c DESC", [$from, $to]); $stot = array_sum(array_column($src, 'c'));
$cogs = (float)val("SELECT COALESCE(SUM(oi.cost*oi.qty),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status IN " . REV_STATUS . " AND DATE(o.created_at) BETWEEN ? AND ?", [$from, $to]); $exp = (float)val('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date BETWEEN ? AND ?', [$from, $to]); $net = $revN - $cogs - $exp;
?>
<div class="dashboard-page">
<div class="welcome"><div class="w-txt"><h1>Welcome back, <?= e(explode(' ', user()['name'])[0]) ?>! 👋</h1><p>Here's what's happening with your store today.</p></div>
<form class="range"><?php foreach (['7d' => '7D', '30d' => '30D', '1m' => 'This Month', '1y' => '1Y'] as $k => $l) echo '<button name="range" value="' . $k . '" class="' . ($rg === $k ? 'on' : '') . '">' . $l . '</button>'; ?></form></div>
<div class="cards"><?php foreach ($cards as $i => $c): ?><div class="kpi c3d <?= $c[4] ?>"><span class="ki"><?= $c[3] ?></span><div class="kt"><small><?= $c[0] ?></small><b><?= $c[1] ?></b><em class="<?= $c[2] >= 0 ? 'up' : 'down' ?>"><?= $c[2] >= 0 ? '↑' : '↓' ?> <?= abs($c[2]) ?>%</em></div><canvas class="spark" id="sp<?= $i ?>" height="46"></canvas></div><?php endforeach; ?></div>
<div class="grid2"><div class="panel"><div class="panel-h"><h3>📈 Revenue Overview</h3><span class="muted"><?= date('d M', strtotime($from)) ?> – <?= date('d M Y', strtotime($to)) ?></span></div><div class="chart-box"><canvas id="revChart"></canvas></div></div>
<div class="panel"><div class="panel-h"><h3>🍩 Order Status</h3></div><div class="chart-box sm"><canvas id="stChart"></canvas></div></div></div>
<?php if (can('finance')): ?><div class="cards three"><div class="mini c3d"><small>Gross Revenue</small><b><?= money($revN) ?></b></div><div class="mini c3d"><small>Product Cost + Expenses</small><b><?= money($cogs + $exp) ?></b></div><div class="mini c3d <?= $net >= 0 ? 'profit' : 'loss' ?>"><small><?= $net >= 0 ? '📈 Net Profit' : '📉 Net Loss' ?></small><b><?= money(abs($net)) ?></b></div></div><?php endif; ?>
<div class="grid3"><div class="panel"><div class="panel-h"><h3>🧾 Recent Orders</h3><a class="abtn sm ghost" href="orders.php">View All</a></div><div class="table-wrap"><table class="atbl"><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th></tr>
<?php foreach ($recent as $o) echo '<tr><td class="mono"><a href="orders.php?view=' . $o['id'] . '">' . e($o['order_no']) . '</a></td><td>' . e($o['name']) . '</td><td>' . money($o['total']) . '</td><td><span class="pill s-' . $o['status'] . '">' . ucfirst($o['status']) . '</span></td></tr>'; if (!$recent) echo '<tr><td colspan="4" class="empty">No orders yet</td></tr>'; ?></table></div></div>
<div class="panel"><div class="panel-h"><h3>🏆 Top Selling</h3><a class="abtn sm ghost" href="products.php">View All</a></div><?php foreach ($top as $p) echo '<div class="tp">' . (has_img($p['image']) ? '<img src="' . img($p['image']) . '" alt="">' : '<span class="tp-ph">' . cat_icon($p['category_id']) . '</span>') . '<div><b>' . e($p['name_en']) . '</b><small>' . money($p['price']) . ' · ' . $p['sold'] . ' sold</small></div></div>'; ?></div>
<?php if (can('content')): ?><div class="panel builder"><div class="panel-h"><h3>🧩 Website Builder</h3><a class="abtn sm" href="sections.php">Edit Now →</a></div><div class="prevframe"><iframe src="../" loading="lazy" tabindex="-1" title="preview"></iframe></div><div class="bl"><a href="menu.php">☰ Menu</a><a href="sections.php">🧩 Sections</a><a href="sliders.php">🖼 Sliders</a><a href="settings.php">⚙ Header/Footer</a></div></div><?php endif; ?></div>
<div class="grid3"><div class="panel"><div class="panel-h"><h3>📊 Visitor Analytics</h3><a class="abtn sm ghost" href="visitors.php">Details</a></div><div class="va"><div class="chart-box xs"><canvas id="devChart"></canvas><div class="dc"><b><?= number_format($vtot) ?></b><small>Visits</small></div></div><div class="vl"><?php foreach (['desktop' => '#22c55e', 'mobile' => '#3b82f6', 'tablet' => '#f59e0b'] as $d => $col) echo '<div><i style="background:' . $col . '"></i>' . ucfirst($d) . '<b>' . ($vtot ? round(($dev[$d] ?? 0) / $vtot * 100) : 0) . '%</b></div>'; ?></div></div>
 <h4 class="sm-h">Traffic Sources</h4><?php foreach ($src as $r) { $pc = $stot ? round($r['c'] / $stot * 100) : 0; echo '<div class="bar-row"><span>' . e($r['s']) . '</span><div class="bar"><i style="width:' . $pc . '%"></i></div><b>' . $pc . '%</b></div>'; } if (!$src) echo '<p class="muted">No visits in this period.</p>'; ?></div>
<div class="alertbox"><b>⚠ Low Stock Alert</b><p><?= count($low) ?> product(s) running low!</p><?php foreach ($low as $p) echo '<a href="products.php?a=edit&id=' . $p['id'] . '">' . e($p['name_en']) . ' <em>' . $p['stock'] . ' left</em></a>'; ?><a class="abtn sm danger" style="margin-top:10px" href="products.php">View Products →</a></div>
<div class="panel"><div class="panel-h"><h3>⚡ Quick Actions</h3></div><div class="qa"><a href="products.php?a=add" class="g">＋<span>Add Product</span></a><a href="orders.php" class="o">🛒<span>Manage Orders</span></a><?php if (can('reports')): ?><a href="reports.php" class="d">📈<span>View Reports</span></a><?php endif; if (can('settings')): ?><a href="settings.php" class="p">⚙<span>Settings</span></a><?php endif; ?></div></div></div>
<script>
var cs=getComputedStyle(document.documentElement),tc=cs.getPropertyValue('--muted').trim();
<?php foreach ($cards as $i => $c): ?>new Chart(document.getElementById('sp<?= $i ?>'),{type:'line',data:{labels:<?= json_encode($labels) ?>,datasets:[{data:<?= json_encode($c[5]) ?>,borderColor:'<?= $c[6] ?>',backgroundColor:'<?= $c[6] ?>22',fill:true,tension:.4,pointRadius:0,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}}}});
<?php endforeach; ?>
new Chart(document.getElementById('revChart'),{type:'line',data:{labels:<?= json_encode($labels) ?>,datasets:[{label:'Revenue',data:<?= json_encode($sRev) ?>,borderColor:'#2b9d5c',backgroundColor:'rgba(43,157,92,.16)',fill:true,tension:.38,pointRadius:3,pointBackgroundColor:'#fff',pointBorderColor:'#2b9d5c',borderWidth:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color:tc,maxTicksLimit:8}},y:{ticks:{color:tc},beginAtZero:true}}}});
new Chart(document.getElementById('stChart'),{type:'doughnut',data:{labels:<?= json_encode(array_map('ucfirst', ORDER_STATUSES)) ?>,datasets:[{data:<?= json_encode(array_map(fn($s) => (int)($st[$s] ?? 0), ORDER_STATUSES)) ?>,backgroundColor:['#e8923a','#3b82f6','#8b5cf6','#06b6d4','#22c55e','#ef4444'],borderWidth:0,hoverOffset:8}]},options:{responsive:true,maintainAspectRatio:false,cutout:'66%',plugins:{legend:{position:'right',labels:{color:tc,usePointStyle:true}}}}});
new Chart(document.getElementById('devChart'),{type:'doughnut',data:{labels:['Desktop','Mobile','Tablet'],datasets:[{data:[<?= (int)($dev['desktop'] ?? 0) ?>,<?= (int)($dev['mobile'] ?? 0) ?>,<?= (int)($dev['tablet'] ?? 0) ?>],backgroundColor:['#22c55e','#3b82f6','#f59e0b'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'70%',plugins:{legend:{display:false}}}});
</script>
